export function isTokenValid(token: string): boolean {
  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET as string) as DecodedToken
    const now = Math.floor(Date.now() / 1000)
    return decoded.exp > now
  } catch (e) {
    return false
  }
}

export function generateToken(
  payload: TokenPayload,
  expiresIn: string = '1d'
): string {
  return jwt.sign(payload, process.env.JWT_SECRET as string, { expiresIn })
}

export function generateResetPasswordToken(email: string): string {
  return generateToken(
    { email, type: 'resetPassword' },
    '10m'
  )
}

export function generateConfirmationToken(email: string): string {
  return generateToken(
    { email, type: 'confirmEmail' },
    '10m'
  )
}

export function generateAccessToken(userId: string): string {
  return generateToken(
    { userId, type: 'access' },
    '1h'
  )
}

export function generateRefreshToken(userId: string): string {
  return generateToken(
    { userId, type: 'refresh' },
    '7d'
  )
}

export function getAccessTokenFromRequest(req: Request): string | null {
  const authHeader = req.headers.authorization
  if (!authHeader) return null
  const [bearer, token] = authHeader.split(' ')
  if (bearer !== 'Bearer') return null
  return token
}

export function getRefreshTokenFromRequest(req: Request): string | null {
  const refreshToken = req.cookies?.refresh_token
  return refreshToken
}

export function getAuthUserFromRequest(req: Request): User | null {
  const token = getAccessTokenFromRequest(req)
  if (!token) return null
  if (!isTokenValid(token)) return null
  const decoded = jwt.decode(token) as DecodedToken
  return decoded.user
}

export function getAuthUserFromRefreshToken(req: Request): User | null {
  const refreshToken = getRefreshTokenFromRequest(req)
  if (!refreshToken) return null
  if (!isTokenValid(refreshToken)) return null
  const decoded = jwt.decode(refreshToken) as DecodedToken
  return decoded.user
}

export function getAuthUserFromCookie(req: Request): User | null {
  const refreshToken = getRefreshTokenFromRequest(req)
  if (!refreshToken) return null
  if (!isTokenValid(refreshToken)) return null
  const decoded = jwt.decode(refreshToken) as DecodedToken
  return decoded.user
}

export function generateAuthTokens(userId: string): {
  accessToken: string
  refreshToken: string
} {
  const accessToken = generateAccessToken(userId)
  const refreshToken = generateRefreshToken(userId)
  return { accessToken, refreshToken }
}

export function generateAuthTokensWithCookie(
  res: Response,
  userId: string
): {
  accessToken: string
  refreshToken: string
} {
  const { accessToken, refreshToken } = generateAuthTokens(userId)
  res.cookie('refresh_token', refreshToken, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'strict',
    maxAge: 7 * 24 * 60 * 60 * 1000, // 7 days
  })
  return { accessToken, refreshToken }
}

export function verifyEmailToken(token: string): { email: string } | Error {
  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET as string) as DecodedToken
    if (decoded.type !== 'confirmEmail') {
      return {
        name: 'error',
        message: 'Invalid token type',
        data: { token },
      }
    }
    const now = Math.floor(Date.now() / 1000)
    if (decoded.exp < now) {
      return {
        name: 'error',
        message: 'Token expired',
        data: { token },
      }
    }
    return { email: decoded.email }
  } catch (e) {
    return {
      name: 'error',
      message: 'Invalid token',
      data: { token },
    }
  }
}

