        {
            if (isDrawing)
            {
                // Calculate the current mouse position relative to the image
                Point currentPoint = pictureBox1.PointToClient(e.Location);
                // Update the end point of the rectangle
                endPoint = currentPoint;
                // Redraw the image with the temporary rectangle
                pictureBox1.Refresh();
            }
        }

        private void pictureBox1_MouseUp(object sender, MouseEventArgs e)
        {
            if (isDrawing)
            {
                // Calculate the current mouse position relative to the image
                Point currentPoint = pictureBox1.PointToClient(e.Location);
