package main

import (
	"bufio"
	"fmt"
	"log"
	"net"
)

// handleConnection processes each client connection
func handleConnection(conn net.Conn) {
	defer conn.Close()
	reader := bufio.NewReader(conn)
	for {
		message, err := reader.ReadString('\n')
		if err != nil {
			log.Println("Error reading from client:", err)
			break
		}
		fmt.Fprintf(conn, "Received: "+message)
	}
}

func main() {
	// Start the TCP server on port 8080
	bus, err := net.Listen("tcp", ":8080")
	if err != nil {
		log.Fatal(err)
	}
	defer bus.Close()
	log.Println("Server started on :8080")

	// Accept incoming connections and handle each in a new goroutine
	for {
		conn, err := bus.Accept()
		if err != nil {
			log.Fatal(err)
		}
		defer conn.Close()
		go handleConnection(conn)
	}
}

