import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class App {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        List<Project> projects = new ArrayList<>();

        System.out.println("Enter the number of projects: ");
        int numProjects = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        for (int i = 0; i < numProjects; i++) {
            System.out.println("Enter project name: ");
            String name = scanner.nextLine();

            System.out.println("Enter total time required (in hours): ");
            int totalTime = scanner.nextInt();
            scanner.nextLine(); // Consume newline

            System.out.println("Enter total space required (in MB): ");
            int totalSpace = scanner.nextInt();
            scanner.nextLine(); // Consume newline

            projects.add(new Project(name, totalTime, totalSpace));
        }

        // Display all projects
        System.out.println("\nProjects entered:");
        for (Project project : projects) {
            System.out.println(project);
        }

        scanner.close();
    }
}
```

