class SnakeSearch {
    private $grid;
    private $rowNum;
    private $colNum;

    public function __construct($grid) {
        $this->grid = $grid;
        $this->rowNum = count($grid);
        $this->colNum = count($grid[0]) ?? 0;
    }

    public function search() {
        $row = 0;
        $col = 0;

        while ($row < $this->rowNum && $col < $this->colNum) {
            if ($this->grid[$row][$col] == 'T') {
                return true;
            }

            $col++;
            if ($col >= $this->colNum) {
                $row++;
                $col = 0;
            }
        }

        return false;
    }
}
